const D = { energy: .6, scale: 1, density: .5, speed: 1, hue: 28, crackle: .6, x: .5, y: .5, style: 'javanese_soga', seed: 0, alpha: 100 };
const P = Object.assign({}, D, (window.state.P && window.state.P.__SLOT__) || {});
const S = window.state.__SLOT__ || (window.state.__SLOT__ = {});
const K = window.state.clk || { t:0, cps:.5, beat:0, bar:0, cyc:0, phase:0, pulse:0, swell:0, section:0, intensity:.6, fps:60 };
const A = window.state.audio || { bass:0, lowmid:0, mid:0, treble:0, rms:0, fft:[] };

const uMin=Math.min(width,height), t=K.t||0;
const drift=0.9*Math.sin(t*0.61)+0.5*Math.sin(t*1.43+1.7)+0.32*Math.sin(t*2.29);
const fr=i=>{ const s=Math.sin(i*127.1+P.seed*311.7)*43758.5453; return s-Math.floor(s); };
function tone(style,hue){
  if(style==='indigo_biru') return {grd:[218,.70,.34], wax:[210,.10,.88], acc:[hue,.55,.62], vein:[218,.60,.10], veinLight:false};
  if(style==='peranakan')   return {grd:[338,.55,.50], wax:[46,.30,.92], acc:[172,.55,.62], vein:[300,.55,.14], veinLight:false};
  if(style==='malam_negative') return {grd:[hue,.45,.12], wax:[hue+6,.30,.40], acc:[hue+20,.40,.55], vein:[42,.20,.72], veinLight:true};
  if(style==='hand_drawn_tulis') return {grd:[32,.34,.48], wax:[40,.16,.82], acc:[8,.42,.52], vein:[26,.50,.14], veinLight:false};
  return {grd:[28,.60,.44], wax:[40,.22,.84], acc:[10,.60,.50], vein:[24,.65,.10], veinLight:false}; // javanese_soga
}
const T=tone(P.style,P.hue);

const key=[P.style,P.seed,Math.round(P.density*30),Math.round(P.hue),Math.round(P.scale*20),width>height?1:0].join('_');
if(S.mkey!==key || !S.g){
  S.mkey=key;
  const BW=Math.max(360,Math.min(680,Math.round(width/2.1))), BH=Math.max(120,Math.round(BW*height/width));
  const g=createGraphics(BW,BH); g.pixelDensity(1); g.colorMode(HSB,360,100,100,100); g.noStroke();
  g.fill(T.grd[0],T.grd[1]*100,T.grd[2]*100); g.rect(0,0,BW,BH);
  // kawung / ceplok motif — grid of overlapping quatrefoil ellipses in wax-cream
  const cell=BW/(3.2+P.density*4)/P.scale, cols=Math.ceil(BW/cell)+2, rows=Math.ceil(BH/cell)+2;
  for(let r=-1;r<rows;r++) for(let c=-1;c<cols;c++){
    const cx=c*cell+ (r&1?cell/2:0), cy=r*cell*0.86;
    g.push(); g.translate(cx,cy);
    for(let k=0;k<4;k++){ const a=k*Math.PI/2;
      g.fill(T.wax[0],T.wax[1]*100,T.wax[2]*100,92);
      g.push(); g.rotate(a); g.ellipse(cell*0.30,0,cell*0.52,cell*0.34); g.pop(); }
    g.fill(T.acc[0],T.acc[1]*100,T.acc[2]*100,80); g.ellipse(0,0,cell*0.24,cell*0.24);
    // isen fine dots
    g.fill(T.wax[0],T.wax[1]*100,T.wax[2]*100,55);
    for(let d=0;d<6;d++){ const ang=d*1.047+ (r+c)*0.4; g.ellipse(Math.cos(ang)*cell*0.42,Math.sin(ang)*cell*0.42,cell*0.05,cell*0.05); }
    g.pop();
  }
  // fine cloth grain
  g.stroke(0,0,0,4); g.strokeWeight(1);
  for(let yy=0;yy<BH;yy+=3) g.line(0,yy,BW,yy);
  g.noStroke();
  S.g=g;
  // crackle veins in normalized coords
  const nV=Math.round(18+P.density*70); const veins=[];
  for(let i=0;i<nV;i++){
    let x=fr(i*5+1), y=fr(i*5+2), h=fr(i*5+3)*6.283;
    const steps=Math.round(16+fr(i*5+4)*46), st=0.006+fr(i*5+5)*0.004;
    const pts=[[x,y]];
    for(let s=0;s<steps;s++){ h += (fr(i*13+s)-0.5)*0.9 + 0.3*Math.sin(x*11+y*7); x+=Math.cos(h)*st; y+=Math.sin(h)*st;
      if(x<-0.05||x>1.05||y<-0.05||y>1.05) break; pts.push([x,y]); }
    if(pts.length>3) veins.push({pts, off:fr(i*7+9), sp:0.4+fr(i*7+3)});
  }
  S.veins=veins;
}

push();
imageMode(CENTER);
const ov=1.09, ddx=0.028*uMin*drift, ddy=0.028*uMin*Math.sin(t*0.33+1.4);
image(S.g, width/2+ddx, height/2+ddy, width*ov, height*ov);

// dye-development sweep (deepen colour in a travelling front)
blendMode(MULTIPLY); noStroke();
const fx=(0.5+0.55*Math.sin(t*0.16*P.speed))*width;
for(let i=0;i<24;i++){ const w=width/24, x0=i*w; const dd=Math.abs(x0+w/2-fx)/width; const a=Math.max(0,1-dd*2)*(6+10*P.energy);
  fill(T.grd[0],T.grd[1]*100,18,a); rect(x0,0,w+1,height); }
blendMode(BLEND);

// crackle veins — drawn live, with a travelling wet-dye seep bead
const cr=P.crackle;
translate(width/2+ddx, height/2+ddy); scale(ov); translate(-width/2,-height/2);
const light=T.veinLight;
strokeCap(ROUND); noFill();
for(let v=0;v<S.veins.length;v++){
  const V=S.veins[v], pts=V.pts;
  stroke(T.vein[0], T.vein[1]*100, T.vein[2]*100, (36+40*cr));
  strokeWeight(Math.max(0.7, uMin*0.0016*(0.7+cr)));
  beginShape();
  for(let i=0;i<pts.length;i++) vertex(pts[i][0]*width, pts[i][1]*height);
  endShape();
  // seep bead travelling along the vein (wet pooled dye)
  const s=((t*0.09*V.sp*P.speed + V.off)%1+1)%1; const idx=Math.floor(s*(pts.length-1)); const p=pts[idx];
  if(p){ const glowA=(0.4+0.6*P.energy)*(0.5+0.5*Math.sin(t*1.7+v));
    if(light) stroke(46,20,95, 40*glowA); else stroke(T.grd[0],T.grd[1]*100,6, 46*glowA);
    strokeWeight(Math.max(1.2, uMin*0.004*(0.6+cr)));
    const i2=Math.min(pts.length-1,idx+1); line(p[0]*width,p[1]*height, pts[i2][0]*width, pts[i2][1]*height);
  }
}
pop();
if(P.alpha<100){ push(); noStroke(); fill(T.grd[0],T.grd[1]*100,T.grd[2]*100,100-P.alpha); rect(0,0,width,height); pop(); }
